<template><view class="page"><PageHead title="我们都在听"/><view class="content"><view class="title">有问题，找青禾</view><view class="subtitle">你的每一条建议，我们都会认真对待</view><view class="chips" style="margin:30rpx 0"><view v-for="t in tabs" :key="t.id" :class="['chip',{selected:tab===t.id}]" @click="tab=t.id">{{t.name}}</view></view><template v-if="tab==='help'"><view v-for="q in questions" :key="q.title" class="card"><view class="bold">{{q.title}}</view><view class="subtitle" style="line-height:1.8">{{q.answer}}</view></view></template><template v-if="tab==='feedback'"><view class="card"><textarea v-model="content" placeholder="告诉我们遇到了什么问题，订单问题请附上订单编号（5至1000字）" maxlength="1000" class="feedback-input"/><button class="btn" :disabled="busy" :loading="busy" @click="submit">提交反馈</button></view></template><template v-if="tab==='messages'"><view v-for="f in feedback" :key="f.id" class="card"><view>{{f.content}}</view><view class="divider"/><view class="small" :class="f.reply?'link':'muted'">{{f.reply?'客服回复：'+f.reply:'已收到，客服将尽快回复你'}}</view><view class="tiny muted" style="margin-top:15rpx">{{String(f.created_at).slice(0,16)}}</view></view><view v-if="!feedback.length" class="empty">暂时没有反馈消息</view></template></view></view></template>
<script setup>
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageHead from '../../components/PageHead.vue';import {request,ensureLogin,state,toast} from '../../lib/api';const tab=ref('help'),feedback=ref([]),content=ref(''),busy=ref(false);const tabs=[{id:'help',name:'常见问题'},{id:'feedback',name:'意见反馈'},{id:'messages',name:'我的消息'}];const questions=[{title:'如何下单和取餐？',answer:'选择商家和菜品，添加购物车后去结算。外卖配送需填写地址，到店自取可凭订单取餐码领取。'},{title:'目前会真实扣款吗？',answer:'当前为模拟支付体验，点击模拟支付不会产生真实扣款。商家接单后会更新制作和配送进度。'},{title:'如何取消订单？',answer:'未支付订单可以在订单详情中取消，15分钟未支付也会自动取消。已支付订单如有问题，请提交反馈并附上订单编号。'},{title:'优惠券和积分怎么使用？',answer:'新用户登录领取满12减3优惠券；每日签到获得10积分，完成订单也可获得积分，100积分可兑换满20减5优惠券。'}];async function load(){if(state.token)try{feedback.value=await request('/feedback')}catch{}}async function submit(){busy.value=true;try{await ensureLogin();await request('/feedback','POST',{content:content.value});content.value='';toast('已收到你的反馈');tab.value='messages';await load()}catch{}finally{busy.value=false}}onLoad(o=>{tab.value=o.tab||'help';load()});
</script><style scoped>.feedback-input{height:300rpx;width:100%;font-size:27rpx;line-height:1.8;margin-bottom:20rpx}</style>
